    return 'Yalnızca $agent terminali durduruldu: $error';
  }

  @override
  String agentStopFailed(String agent, String error) {
    return '$agent durdurulamadı: $error';
  }

  @override
  String agentStopOlderDevice(String computer) {
    return '$computer üzerinde daha yeni bir Antenna gerekir';
  }

  @override
  String codeStateStoppedFrom(String computer) {
    return '$computer üzerinden durduruldu';
  }

  @override
  String get taskUrgent => 'Acil: çalışanı şimdi yarıda kes';

  @override
  String get taskUrgentTip =>
      'Çalışan mevcut turunu durdurur ve üzerinde çalışırken bile görevi yorumlarınızla birlikte hemen geri alır.';
}
